//! The staff alert tones, embedded at build time (the same WAV files the Go agent embeds
//! from `internal/player/tones`, generated by its `tools/gen-tones`).

macro_rules! tones {
    ($($name:literal),* $(,)?) => {
        /// `(name, WAV bytes)` for every embedded tone.
        pub const TONES: &[(&str, &[u8])] = &[
            $(($name, include_bytes!(concat!("../assets/tones/", $name, ".wav")))),*
        ];
    };
}

tones!(
    "chime", "guest", "service", "bell", "marimba", "dingdong", "glass", "harp", "celesta", "gong",
    "steward",
);

/// The WAV bytes of a tone; `None` for a name the web Settings page has but this build
/// does not (config drift is an error to log, never a panic).
pub fn tone(name: &str) -> Option<&'static [u8]> {
    TONES.iter().find(|(n, _)| *n == name).map(|(_, d)| *d)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_tone_is_a_wav() {
        assert_eq!(TONES.len(), 11);
        for (name, data) in TONES {
            assert!(
                data.starts_with(b"RIFF") && &data[8..12] == b"WAVE",
                "{name}"
            );
        }
        assert!(tone(crate::mode::DEFAULT_TONE).is_some());
        assert!(tone("no-such-tone").is_none());
    }
}
